PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE programs (
  id            TEXT PRIMARY KEY,            -- slug: host or platform:id
  name          TEXT NOT NULL,
  platform      TEXT NOT NULL DEFAULT 'self', -- self|hackerone|bugcrowd|immunefi|cantina|c4|sherlock|codehawks|hackenproof|intigriti|yeswehack
  homepage      TEXT,
  policy_url    TEXT,
  policy_sha    TEXT,                         -- hash of policy text at last fetch
  policy_text   TEXT,
  -- gating field. every dispatch reads this. never inferred from prose elsewhere.
  automation    TEXT NOT NULL DEFAULT 'unknown'
                CHECK (automation IN ('allowed','not_mentioned','prohibited','unknown')),
  reward        TEXT NOT NULL DEFAULT 'unknown'
                CHECK (reward IN ('monetary','swag','recognition','none','unknown')),
  safe_harbour  INTEGER NOT NULL DEFAULT 0,
  responsiveness REAL,                        -- 0..1, updated from outcomes
  priority      REAL NOT NULL DEFAULT 0.5,
  status        TEXT NOT NULL DEFAULT 'new'
                CHECK (status IN ('new','crawled','parsed','active','paused','dead')),
  discovered_at INTEGER NOT NULL,
  last_checked  INTEGER,
  next_check    INTEGER,
  meta          TEXT NOT NULL DEFAULT '{}'
);
CREATE TABLE assets (
  id          TEXT PRIMARY KEY,
  program_id  TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL,                  -- domain|host|url|api|cidr|chain_address|repo|apk|ipa
  value       TEXT NOT NULL,
  in_scope    INTEGER NOT NULL DEFAULT 1,
  chain_id    INTEGER,
  first_seen  INTEGER NOT NULL,
  last_seen   INTEGER NOT NULL,
  meta        TEXT NOT NULL DEFAULT '{}',
  UNIQUE(program_id, kind, value)
);
CREATE TABLE engagements (
  id               TEXT PRIMARY KEY,
  program_id       TEXT NOT NULL REFERENCES programs(id),
  title            TEXT NOT NULL,
  brief            TEXT NOT NULL,             -- JSON, produced by the intake wizard
  authorization_ref TEXT NOT NULL,            -- exact policy sentence relied on
  window_start     INTEGER NOT NULL,
  window_end       INTEGER NOT NULL,
  time_box_minutes INTEGER NOT NULL DEFAULT 240,
  max_mutability   TEXT NOT NULL DEFAULT 'read'
                   CHECK (max_mutability IN ('read','simulate','mutate','destructive')),
  status           TEXT NOT NULL DEFAULT 'open'
                   CHECK (status IN ('draft','open','paused','closed','abandoned')),
  created_at       INTEGER NOT NULL,
  closed_at        INTEGER,
  spend_cents      INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE probes (
  id            TEXT PRIMARY KEY,
  engagement_id TEXT NOT NULL REFERENCES engagements(id) ON DELETE CASCADE,
  playbook_id   TEXT NOT NULL,
  probe_id      TEXT NOT NULL,
  target        TEXT NOT NULL,
  mutability    TEXT NOT NULL,
  verdict       TEXT NOT NULL DEFAULT 'pending'
                CHECK (verdict IN ('pending','allow','deny','needs_approval')),
  state         TEXT NOT NULL DEFAULT 'queued'
                CHECK (state IN ('queued','running','done','skipped','error')),
  started_at    INTEGER, finished_at INTEGER,
  output_digest TEXT,
  error         TEXT,
  UNIQUE(engagement_id, playbook_id, probe_id, target)
);
CREATE TABLE findings (
  id           TEXT PRIMARY KEY,
  engagement_id TEXT REFERENCES engagements(id) ON DELETE SET NULL,
  program_id   TEXT REFERENCES programs(id),
  asset_id     TEXT REFERENCES assets(id),
  title        TEXT NOT NULL,
  cls          TEXT NOT NULL,                 -- playbook/class id
  severity     TEXT NOT NULL DEFAULT 'info'
               CHECK (severity IN ('critical','high','medium','low','info')),
  confidence   TEXT NOT NULL DEFAULT 'tentative'
               CHECK (confidence IN ('tentative','firm','confirmed')),
  proof_state  TEXT NOT NULL DEFAULT 'hypothesis'
               CHECK (proof_state IN ('hypothesis','partial','proven','disproved')),
  status       TEXT NOT NULL DEFAULT 'candidate'
               CHECK (status IN ('candidate','triaged','reported','accepted','rejected','duplicate','fixed')),
  dedupe_key   TEXT NOT NULL,
  summary      TEXT,
  impact       TEXT,
  remediation  TEXT,
  repro        TEXT,                           -- JSON array of steps actually executed
  created_at   INTEGER NOT NULL,
  updated_at   INTEGER NOT NULL
);
CREATE TABLE evidence (
  id         TEXT PRIMARY KEY,
  finding_id TEXT NOT NULL REFERENCES findings(id) ON DELETE CASCADE,
  type       TEXT NOT NULL,                   -- http_exchange|command_output|code_reference|screenshot|tx_trace|other
  payload    TEXT NOT NULL,                   -- JSON
  digest     TEXT NOT NULL,
  created_at INTEGER NOT NULL
);
CREATE TABLE approvals (
  id          TEXT PRIMARY KEY,
  fingerprint TEXT NOT NULL,
  action      TEXT NOT NULL,                  -- JSON
  reason      TEXT NOT NULL,
  status      TEXT NOT NULL DEFAULT 'pending'
              CHECK (status IN ('pending','approved','denied','expired')),
  requested_at INTEGER NOT NULL,
  decided_at   INTEGER,
  operator     TEXT
);
CREATE TABLE ledger (
  seq       INTEGER PRIMARY KEY,
  ts        INTEGER NOT NULL,
  kind      TEXT NOT NULL,
  payload   TEXT NOT NULL,
  prev_hash TEXT NOT NULL,
  hash      TEXT NOT NULL UNIQUE
);
CREATE TABLE quota (
  day     TEXT NOT NULL,                      -- YYYY-MM-DD (UTC)
  bucket  TEXT NOT NULL,                      -- subrequests|llm_tokens|r2_ops|d1_rows|neurons
  used    INTEGER NOT NULL DEFAULT 0,
  cap     INTEGER NOT NULL,
  PRIMARY KEY(day, bucket)
);
CREATE TABLE heartbeats (
  source TEXT PRIMARY KEY,                    -- worker|cron|crawler|sentinel|actions
  ts     INTEGER NOT NULL,
  note   TEXT
);
CREATE TABLE llm_log (
  id        TEXT PRIMARY KEY,
  ts        INTEGER NOT NULL,
  provider  TEXT NOT NULL,
  model     TEXT NOT NULL,
  prompt_sha TEXT NOT NULL,
  tokens_in INTEGER, tokens_out INTEGER,
  latency_ms INTEGER,
  ok        INTEGER NOT NULL,
  error     TEXT
);
CREATE TABLE corpus (
  id        TEXT PRIMARY KEY,
  firm      TEXT, project TEXT, year INTEGER,
  severity  TEXT, cls TEXT, fix_status TEXT, review_type TEXT,
  title     TEXT, body TEXT, url TEXT,
  signals   TEXT,                             -- YOUR enrichment: detection signals
  added_at  INTEGER NOT NULL
);
CREATE TABLE evals (
  id         TEXT PRIMARY KEY,
  ts         INTEGER NOT NULL,
  playbook_id TEXT NOT NULL,
  corpus_n   INTEGER NOT NULL,
  tp INTEGER NOT NULL, fp INTEGER NOT NULL, fn INTEGER NOT NULL,
  precision  REAL, recall REAL,
  notes      TEXT
);
CREATE TABLE watchlist (
  id         TEXT PRIMARY KEY,
  chain_id   INTEGER NOT NULL,
  address    TEXT NOT NULL,
  label      TEXT NOT NULL,
  rules      TEXT NOT NULL DEFAULT '[]',      -- JSON array of rule ids
  last_block INTEGER NOT NULL DEFAULT 0,
  enabled    INTEGER NOT NULL DEFAULT 1,
  UNIQUE(chain_id, address)
);
CREATE TABLE alerts (
  id         TEXT PRIMARY KEY,
  watch_id   TEXT REFERENCES watchlist(id) ON DELETE CASCADE,
  rule       TEXT NOT NULL,
  severity   TEXT NOT NULL,
  payload    TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  sent_at    INTEGER,
  acked_at   INTEGER
);
CREATE TABLE intake_sessions (
  chat_id    INTEGER PRIMARY KEY,
  state      TEXT NOT NULL DEFAULT 'idle',
  draft      TEXT NOT NULL DEFAULT '{}',
  step       INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL
);
CREATE TABLE kv (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  ts    INTEGER NOT NULL DEFAULT (unixepoch())
);
CREATE TABLE hunts (
  id            TEXT PRIMARY KEY,
  program_id    TEXT REFERENCES programs(id),
  engagement_id TEXT REFERENCES engagements(id),
  repo          TEXT,
  commit_sha    TEXT,
  contract      TEXT,
  fork_block    INTEGER,
  stage         TEXT NOT NULL DEFAULT 'rank'
                CHECK (stage IN ('rank','lead','prime','attempt','judge','done','failed')),
  leads_n       INTEGER NOT NULL DEFAULT 0,
  attempts_n    INTEGER NOT NULL DEFAULT 0,
  proven_n      INTEGER NOT NULL DEFAULT 0,
  stopped_because TEXT,
  created_at    INTEGER NOT NULL,
  updated_at    INTEGER NOT NULL
);
CREATE TABLE proofs (
  id          TEXT PRIMARY KEY,
  hunt_id     TEXT NOT NULL REFERENCES hunts(id) ON DELETE CASCADE,
  playbook    TEXT NOT NULL,
  test_name   TEXT NOT NULL,
  file        TEXT,
  line        INTEGER,
  verdict     TEXT NOT NULL DEFAULT 'inconclusive'
              CHECK (verdict IN ('proven','partial','disproved','inconclusive')),
  confidence  TEXT NOT NULL DEFAULT 'tentative'
              CHECK (confidence IN ('confirmed','firm','tentative')),
  claim       TEXT,
  reasons     TEXT NOT NULL DEFAULT '[]',
  artifact    TEXT,
  created_at  INTEGER NOT NULL,
  UNIQUE(hunt_id, test_name)
);
CREATE TABLE learning_outcomes (
  id                 TEXT PRIMARY KEY,
  cls                TEXT NOT NULL,           -- playbook corpus class id
  playbook           TEXT NOT NULL,           -- playbook that produced it
  verdict            TEXT NOT NULL
                     CHECK (verdict IN ('proven','partial','disproved','inconclusive')),
  target_fingerprint TEXT,                    -- stable hash of the target
  measured_before    REAL,                    -- optional measured effect
  measured_after     REAL,
  created_at         INTEGER NOT NULL
);
CREATE TABLE corpus_sources (
  id            TEXT PRIMARY KEY,
  source        TEXT NOT NULL,                -- ghsa|nvd|cvelist|defihacklabs|jsonl...
  url           TEXT,                         -- where the rows came from
  licence       TEXT,                         -- SPDX id or explicit "none"
  rows_ingested INTEGER NOT NULL DEFAULT 0,
  digest_version TEXT,                        -- digest the rows landed in
  ingested_at   INTEGER NOT NULL,
  UNIQUE(source, digest_version)
);
CREATE TABLE desk_universe (
  mint           TEXT PRIMARY KEY,
  symbol         TEXT,
  name           TEXT,
  pair_address   TEXT,
  dex            TEXT,
  pair_created_at INTEGER NOT NULL,           -- ms since epoch, from the pair
  first_seen     INTEGER NOT NULL,            -- seconds, our clock
  last_seen      INTEGER NOT NULL,
  mcap_usd       REAL NOT NULL DEFAULT 0,
  liq_usd        REAL NOT NULL DEFAULT 0,
  vol_1h_usd     REAL NOT NULL DEFAULT 0,
  vol_24h_usd    REAL NOT NULL DEFAULT 0,
  price_usd      REAL NOT NULL DEFAULT 0,
  price_6h_low   REAL NOT NULL DEFAULT 0,
  price_24h_low  REAL NOT NULL DEFAULT 0,
  holders        INTEGER NOT NULL DEFAULT 0,
  -- scout verdict: 'in' means the coarse gates passed. It is NOT a buy.
  state          TEXT NOT NULL DEFAULT 'in'
                 CHECK (state IN ('in','scored','passed','killed','expired')),
  snapshot       TEXT NOT NULL DEFAULT '{}'   -- raw DexScreener pair at scout time
);
CREATE TABLE desk_scores (
  id          TEXT PRIMARY KEY,
  mint        TEXT NOT NULL,
  ts          INTEGER NOT NULL,
  total       REAL NOT NULL,
  subscores   TEXT NOT NULL,                  -- JSON {component: {raw, score, floor, weight}}
  floor_failed TEXT NOT NULL DEFAULT '[]',    -- JSON[] of components under their floor
  passed      INTEGER NOT NULL DEFAULT 0,     -- 1 only when total>=70 AND no floor_failed
  why         TEXT NOT NULL DEFAULT ''        -- the stored "why", not just messaged
);
CREATE TABLE desk_kills (
  id           TEXT PRIMARY KEY,
  mint         TEXT NOT NULL,
  symbol       TEXT,
  ts           INTEGER NOT NULL,
  reason       TEXT NOT NULL,                 -- stable code, see desk/reasons.ts
  detail       TEXT NOT NULL DEFAULT '',      -- human sentence, numbers inline
  snapshot     TEXT NOT NULL DEFAULT '{}',    -- the full input that produced the kill
  -- filled in later by calibration: did avoiding this token turn out wrong?
  outcome      TEXT NOT NULL DEFAULT 'unknown'
               CHECK (outcome IN ('unknown','dodged','missed_3x','missed_10x')),
  outcome_ts   INTEGER,
  outcome_price REAL
);
CREATE TABLE desk_positions (
  id             TEXT PRIMARY KEY,
  mint           TEXT NOT NULL,
  symbol         TEXT,
  mode           TEXT NOT NULL DEFAULT 'paper' CHECK (mode IN ('paper','live')),
  opened_at      INTEGER NOT NULL,
  closed_at      INTEGER,
  entry_price    REAL NOT NULL,
  confirmation_price REAL,                    -- second-half entry, NULL until filled
  size_usd       REAL NOT NULL,               -- total intended position size
  filled_usd     REAL NOT NULL DEFAULT 0,
  qty            REAL NOT NULL DEFAULT 0,
  stop_price     REAL NOT NULL,
  peak_price     REAL NOT NULL,
  trail_armed    INTEGER NOT NULL DEFAULT 0,
  trail_pct      REAL NOT NULL DEFAULT 0.12,
  atr14          REAL NOT NULL DEFAULT 0,
  liq_at_entry   REAL NOT NULL,
  state          TEXT NOT NULL DEFAULT 'open'
                 CHECK (state IN ('open','closed')),
  exit_price     REAL,
  exit_reason    TEXT,                        -- reason code, see desk/reasons.ts
  pnl_usd        REAL,
  pnl_pct        REAL,
  thesis_id      TEXT
);
CREATE TABLE desk_fills (
  id           TEXT PRIMARY KEY,
  position_id  TEXT NOT NULL,
  mint         TEXT NOT NULL,
  ts           INTEGER NOT NULL,
  side         TEXT NOT NULL CHECK (side IN ('buy','sell')),
  tranche      TEXT NOT NULL DEFAULT 'entry' CHECK (tranche IN ('entry','confirmation','exit','stop')),
  qty          REAL NOT NULL,
  price        REAL NOT NULL,
  notional_usd REAL NOT NULL,
  -- what paper mode modelled on top of the pool price. Zero for live fills,
  -- where the chain charged the real amount.
  lp_fee_usd   REAL NOT NULL DEFAULT 0,
  prio_fee_usd REAL NOT NULL DEFAULT 0,
  slippage_usd REAL NOT NULL DEFAULT 0,
  price_impact REAL NOT NULL DEFAULT 0,       -- fraction, e.g. 0.0042
  mode         TEXT NOT NULL DEFAULT 'paper' CHECK (mode IN ('paper','live'))
);
CREATE TABLE desk_theses (
  id         TEXT PRIMARY KEY,
  mint       TEXT NOT NULL,
  ts         INTEGER NOT NULL,
  source     TEXT NOT NULL DEFAULT 'deterministic'
             CHECK (source IN ('deterministic','llm','llm_failed')),
  score_id   TEXT,
  body       TEXT NOT NULL,
  model      TEXT
);
CREATE TABLE desk_calibration (
  id            TEXT PRIMARY KEY,
  ts            INTEGER NOT NULL,
  window_start  INTEGER NOT NULL,
  window_end    INTEGER NOT NULL,
  rows          TEXT NOT NULL,                -- JSON[] per reason code
  totals        TEXT NOT NULL DEFAULT '{}',   -- JSON {kills, dodge_rate, ...}
  note          TEXT NOT NULL DEFAULT ''
);
CREATE TABLE candidates (
  id                 TEXT PRIMARY KEY,       -- evm:<chain>:<addr-lower> | svm:<cluster>:<addr>
  family             TEXT NOT NULL CHECK (family IN ('evm','svm')),
  chain_id           INTEGER,                -- NULL only for family='svm'; never invented
  address            TEXT NOT NULL,          -- as published, casing preserved
  name               TEXT NOT NULL,
  kind               TEXT NOT NULL DEFAULT 'protocol',  -- protocol|token
  category           TEXT,
  tvl_usd            REAL,                   -- display ONLY; not a ranking input
  -- first-class: alerts and the UI rank and filter on this without re-joining
  has_programme      INTEGER NOT NULL DEFAULT 0 CHECK (has_programme IN (0,1)),
  programme_id       TEXT,
  payout_cap_usd     REAL,                   -- NULL = unmeasured, NOT zero
  automation_allowed INTEGER NOT NULL DEFAULT 0 CHECK (automation_allowed IN (0,1)),
  automation_reason  TEXT NOT NULL DEFAULT 'no-programme',
  automation_class   TEXT CHECK (automation_class IN ('allowed','not_mentioned','prohibited','unknown')),
  fund_addresses     TEXT NOT NULL DEFAULT '[]',   -- JSON array, filtered
  fork_target        TEXT,                   -- NULL unless a non-token address survived
  fund_state         TEXT NOT NULL DEFAULT 'pending',
  address_is_token   INTEGER NOT NULL DEFAULT 0 CHECK (address_is_token IN (0,1)),
  class_weights      TEXT NOT NULL DEFAULT '{}',   -- JSON {class: weight} from the digest
  ev                 REAL NOT NULL DEFAULT 0,      -- 0 is a refusal, not a small number
  ev_zero_reason     TEXT,
  ev_why             TEXT,
  updated_at         INTEGER NOT NULL
);
CREATE TABLE fund_queue (
  id               TEXT PRIMARY KEY,      -- slug:<name>@<chain-key>
  name             TEXT NOT NULL,
  tvl_code_path    TEXT NOT NULL DEFAULT '',
  raw_url          TEXT NOT NULL DEFAULT '',
  symbol           TEXT,
  address          TEXT,
  tvl_usd          REAL,
  state            TEXT NOT NULL DEFAULT 'queued'
                   CHECK (state IN ('queued','fetched','empty','failed','no-adapter')),
  attempts         INTEGER NOT NULL DEFAULT 0,
  bytes            INTEGER NOT NULL DEFAULT 0,
  addresses_n      INTEGER NOT NULL DEFAULT 0,
  dropped_as_token INTEGER NOT NULL DEFAULT 0,
  fund_addresses   TEXT NOT NULL DEFAULT '[]',
  fork_target      TEXT,
  last_error       TEXT,
  next_attempt     INTEGER NOT NULL DEFAULT 0,
  fetched_at       INTEGER
);
CREATE TABLE scope_snapshots (
  id                 TEXT PRIMARY KEY,
  program_id         TEXT NOT NULL REFERENCES programs(id) ON DELETE CASCADE,
  platform           TEXT NOT NULL,
  kind               TEXT NOT NULL DEFAULT 'unknown',
  payout_cap_usd     REAL,                -- NULL = the platform publishes no per-finding cap
  automation_allowed INTEGER NOT NULL DEFAULT 0 CHECK (automation_allowed IN (0,1)),
  automation_class   TEXT NOT NULL DEFAULT 'unknown'
                     CHECK (automation_class IN ('allowed','not_mentioned','prohibited','unknown')),
  automation_reason  TEXT NOT NULL DEFAULT 'field-absent',
  -- the exact sentence the verdict rests on, so a refusal is checkable
  evidence           TEXT,
  terms_sha          TEXT,
  terms_text         TEXT,
  assets_n           INTEGER NOT NULL DEFAULT 0,
  fetched_at         INTEGER NOT NULL
);
CREATE TABLE desk_flow (
  mint            TEXT PRIMARY KEY,
  ts              INTEGER NOT NULL,           -- seconds, when sampled
  source          TEXT NOT NULL,              -- provider id, e.g. 'rpc-sample'
  unique_buyers   INTEGER,                    -- NULL = not established
  total_buys      INTEGER,
  buy_volume_usd  REAL,
  sell_volume_usd REAL,
  median_buy_usd  REAL,
  avg_buy_usd     REAL,
  unique_buyer_growth_pct REAL,
  bundled_pct     REAL,
  sniper20_pct    REAL,
  dev_cluster_pct REAL,
  smart_wallet_pct REAL,
  atr14_pct       REAL,
  -- provenance of the sample every derived number came from
  sample_sigs     INTEGER NOT NULL DEFAULT 0,
  sample_from_slot INTEGER,
  sample_to_slot  INTEGER,
  usd_basis       TEXT NOT NULL DEFAULT 'mid',
  fields_null     TEXT NOT NULL DEFAULT '[]', -- JSON[] of field names left null
  detail          TEXT NOT NULL DEFAULT ''
);
CREATE TABLE desk_marks (
  id          TEXT PRIMARY KEY,
  mint        TEXT NOT NULL,
  ts          INTEGER NOT NULL,               -- seconds, our clock
  price_usd   REAL NOT NULL,
  liq_usd     REAL,
  mcap_usd    REAL,
  source      TEXT NOT NULL DEFAULT 'dexscreener'
              CHECK (source IN ('dexscreener','rpc','fixture')),
  note        TEXT NOT NULL DEFAULT ''
);
CREATE TABLE desk_probes (
  id             TEXT PRIMARY KEY,
  mint           TEXT NOT NULL,
  ts             INTEGER NOT NULL,
  leg            TEXT NOT NULL CHECK (leg IN ('entry','exit')),
  ok             INTEGER NOT NULL,            -- 1 = simulated transfer succeeded
  signature      TEXT NOT NULL,
  payload_sha256 TEXT NOT NULL,
  err            TEXT NOT NULL DEFAULT '',    -- JSON of the program error, '' when none
  units_consumed INTEGER,
  logs_tail      TEXT NOT NULL DEFAULT '[]'   -- JSON[]
);
CREATE TABLE desk_fill_costs (
  id             TEXT PRIMARY KEY,
  position_id    TEXT NOT NULL,
  mint           TEXT NOT NULL,
  ts             INTEGER NOT NULL,
  side           TEXT NOT NULL CHECK (side IN ('buy','sell')),
  notional_usd   REAL NOT NULL,
  mev_bps        REAL NOT NULL,
  failed_tx_bps  REAL NOT NULL,
  mev_usd        REAL NOT NULL,
  failed_tx_usd  REAL NOT NULL,
  haircut_total_usd REAL NOT NULL
);
PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE corpus_digest (
  version      TEXT PRIMARY KEY,
  source_rows  INTEGER NOT NULL,
  digest       TEXT NOT NULL,
  loaded_at    INTEGER NOT NULL
);
